fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

fn id(text: &str) -> DataId {
    DataId::new(text).expect("id")
}

/// The two files of the fixture as JSON values without their text.
fn liability_files() -> (Value, Value) {
    common::files_from(
        include_str!("../../../tests/golden/data_liability/calibration/genetics.json"),
        include_str!("../../../tests/golden/data_liability/genetics/genome_map.json"),
    )
}

/// The fixture with the repository's life course data.
fn liability_data() -> Data {
    let (calibration, genome_map) = liability_files();
    Data::new(common::definitions(calibration, genome_map).expect("definitions")).expect("checked")
}

/// A change of the two files of the fixture.
type Change = Box<dyn FnOnce(&mut Value, &mut Value)>;

/// The check of the fixture changed by `change`: "ok" or the code of the error.
fn checked(change: impl FnOnce(&mut Value, &mut Value)) -> String {
    let (mut calibration, mut genome_map) = liability_files();
    change(&mut calibration, &mut genome_map);
    match common::definitions(calibration, genome_map) {
        Err(serde) => format!("serde: {serde}"),
        Ok(definitions) => match Data::new(definitions) {
            Ok(_) => "ok".to_owned(),
            Err(error) => error.to_string(),
        },
    }
}

/// The eight liability loci, the first four with `first`, the last four with `last`.
fn liability_loci(first: [u8; 2], last: [u8; 2]) -> Vec<LocusAlleles> {
    (1..=8)
        .map(|n| LocusAlleles {
            locus: id(&format!("test:liability_{n}")),
            copies: if n <= 4 { first } else { last }.to_vec(),
        })
        .collect()
}

fn founder(years: i64, sex: Sex, alleles: Vec<LocusAlleles>) -> Founder {
    Founder {
        born: SimTime::from_secs(-years * Y),
        sex,
        alleles,
    }
}

fn threshold_start() -> Input {
    let late = LocusAlleles {
        locus: id("core:disease_ad_late"),
        copies: vec![1, 0],
    };
    let both = liability_loci([1, 1], [1, 1]);
    Input::Start(Start {
        world_seed: 0xff,
        founder_tag: id("test:threshold5"),
        world_params: WorldParams {
            hereditary_diseases: true,
            nutrition: Vec::new(),
        },
        founders: vec![
            founder(24, Sex::Female, both.clone()),
            founder(26, Sex::Male, both.clone()),
            founder(24, Sex::Female, liability_loci([1, 0], [1, 0])),
            founder(26, Sex::Male, both.clone()),
            founder(30, Sex::Female, liability_loci([1, 1], [1, 0])),
            founder(40, Sex::Male, both.clone()),
            founder(45, Sex::Female, [vec![late], both].concat()),
            founder(30, Sex::Male, Vec::new()),
        ],
        couples: vec![
            Couple { woman: 0, man: 1 },
            Couple { woman: 2, man: 3 },
            Couple { woman: 4, man: 7 },
        ],
        capacity: None,
        pool: None,
    })
}

struct Run {
    world: World,
    out: YearOut,
    log: Vec<LogEntry>,
}

impl Run {
    fn start() -> Run {
        let mut world = World::new(liability_data());
        world.submit(threshold_start()).expect("accepted");
        let log = world.take_log();
        Run {
            world,
            out: YearOut::default(),
            log,
        }
    }

    fn play(&mut self, until: i64) {
        self.world
            .advance_until(&mut self.out, SimTime::from_secs(until), &mut |_| false);
        self.log.extend(self.world.take_log());
    }

    fn save(&self) -> Vec<u8> {
        self.world.save(&self.out.year_hashes).expect("saves")
    }

    /// The entries from `from` on, against the reference: the bytes of each, and its JSON
    /// form where the reference gives it.
    fn assert_entries(&self, from: usize, expected: &[(&str, Option<&str>)]) {
        let entries = &self.log[from..];
        assert_eq!(entries.len(), expected.len(), "entries");
        for (entry, (bytes, json)) in entries.iter().zip(expected) {
            assert_eq!(
                postcard::to_allocvec(entry).expect("encodes"),
                hex(bytes),
                "entry {}",
                serde_json::to_string(entry).expect("json")
            );
            if let Some(json) = json {
                assert_eq!(serde_json::to_string(entry).expect("json"), *json);
            }
        }
    }

    /// Plays up to the second before `at` (its save against `before`), then that second
    /// (its entries and its save against the reference).
    fn second(&mut self, at: i64, before: &str, expected: &[(&str, Option<&str>)], after: &str) {
        self.play(at - 1);
        assert_eq!(self.save(), hex(before));
        let from = self.log.len();
        self.play(at);
        self.assert_entries(from, expected);
        assert_eq!(self.save(), hex(after));
        assert_loads(&self.save());
    }
}

/// The save loads and the loaded world saves the same bytes (ADR-0006 section 6): the load
/// check of the afflictions accepts what the rule gives.
fn assert_loads(bytes: &[u8]) {
    let (world, years) = World::load(bytes, liability_data()).expect("loads");
    assert_eq!(world.save(&years).expect("saves"), bytes);
}

/// The fixture's data hash, and `T` kept with the data: `probit(1 − K)` with `K` 0.01, the
/// recorded bits of the known answer. The repository's data name no trait of liability, so
/// they have no `T`.
#[test]
fn the_threshold_comes_with_the_data() {
    let data = liability_data();
    let code = id("core:disease_liability");
    assert_eq!(data.hash(), DATA_HASH);
    assert_eq!(
        data.threshold(&code).map(f64::to_bits),
        Some(THRESHOLD_BITS)
    );
    assert_eq!(common::data().threshold(&code), None);
}

/// A named liability is the trait of the map named after the disease, with a phenotype row
/// of `h²` the heritability bit for bit and `c²` 0, equal in both ages, and `1 − K` below 1
/// in f64 (else `T` is NaN: review finding); each case below breaks one rule and is
/// `data.disease`. `K` = 2^-53 lies at the edge (the smallest accepted `K` is the next f64
/// above 2^-54, whose complement rounds to 1): accepted, with a finite `T`.
#[test]
fn a_named_liability_must_fit_its_disease() {
    let liability = "core:disease_liability";
    let row = |weights: [f64; 4]| {
        move |c: &mut Value, _: &mut Value| {
            for (name, weight) in ["h2_child", "c2_child", "h2_adult", "c2_adult"]
                .iter()
                .zip(weights)
            {
                c["traits"][0][*name]["value"] = json!(weight);
            }
        }
    };
    fn carrier(c: &mut Value) -> &mut Value {
        &mut c["diseases"][5]["carrier"]["threshold"]
    }
    let cases: [(&str, Change); 9] = [
        (
            "h2 0.5, the heritability 0.6",
            Box::new(row([0.5, 0.0, 0.5, 0.0])),
        ),
        (
            "the heritability one ulp above the row's 0.6",
            Box::new(move |c, _| {
                carrier(c)["heritability"]["value"] = json!(f64::from_bits(0.6_f64.to_bits() + 1));
            }),
        ),
        (
            "c2 0.05 in both ages",
            Box::new(row([0.6, 0.05, 0.6, 0.05])),
        ),
        (
            "h2 child 0.5, adult 0.6",
            Box::new(row([0.5, 0.0, 0.6, 0.0])),
        ),
        (
            "c2 child 0.05, adult 0",
            Box::new(row([0.6, 0.05, 0.6, 0.0])),
        ),
        (
            "a trait of the map with a fitting row, not named after the disease",
            Box::new(move |c, g| {
                let renamed = json!("test:liability");
                g["traits"][0]["id"] = renamed.clone();
                for locus in g["loci"].as_array_mut().expect("loci") {
                    if let Some(Value::Array(loads)) = locus.pointer_mut("/action/additive/loads") {
                        for load in loads.iter_mut().filter(|l| l["trait"] == liability) {
                            load["trait"] = renamed.clone();
                        }
                    }
                }
                c["traits"][0]["trait"] = renamed.clone();
                carrier(c)["liability"] = renamed;
            }),
        ),
        (
            "a trait the map lacks",
            Box::new(move |c, _| carrier(c)["liability"] = json!("test:no_such_trait")),
        ),
        ("no phenotype row", Box::new(|c, _| c["traits"] = json!([]))),
        (
            "the prevalence 1e-20, whose complement rounds to 1",
            Box::new(|c, _| carrier(c)["prevalence"]["value"] = json!(1e-20)),
        ),
    ];
    assert_eq!(checked(|_, _| {}), "ok");
    for (case, change) in cases {
        assert_eq!(checked(change), "data.disease", "{case}");
    }
    let (mut calibration, genome_map) = liability_files();
    carrier(&mut calibration)["prevalence"]["value"] = json!(f64::from_bits(0x3ca0_0000_0000_0000));
    let data = Data::new(common::definitions(calibration, genome_map).expect("definitions"))
        .expect("checked");
    let threshold = data.threshold(&id(liability)).expect("a threshold");
    assert!(threshold.is_finite() && threshold > 8.0, "{threshold}");
}

/// `Start` gives each founder its afflictions: the threshold disease to those with `L > T`
/// (sims 1, 2, 4, 6 and 7), after `core:disease_ad_late` for sim 7 (the order of the data),
/// each with its onset and its death planned.
