/// The whole run: the year hashes, the log, the save and the pedigree at its end.
#[test]
fn threshold_runs_as_the_reference() {
    let mut run = Run::start();
    run.play(END);
    assert_eq!(
        run.out
            .year_hashes
            .iter()
            .map(|y| y.hash)
            .collect::<Vec<_>>(),
        YEAR_HASHES
    );
    assert_eq!(run.log.len(), LOG_ENTRIES);
    assert_eq!(log_hash(&run.log), LOG_HASH);
    assert_eq!(run.save(), hex(SAVE_END));
    assert_loads(&run.save());
    assert_eq!(
        serde_json::to_string(&run.world.pedigree()).expect("json"),
        END_PEDIGREE_JSON
    );
}

/// `L` of every person of the run against the reference, bit for bit, from the genotype of
/// the pedigree, the person's key and its parents' keys (the 4.2 phenotype of the trait;
/// its weights are equal in both ages, so the age does not matter): the disease iff
/// `L > T`.
#[test]
fn the_liability_decides_who_has_the_disease() {
    let data = liability_data();
    let code = id("core:disease_liability");
    let threshold = data.threshold(&code).expect("a threshold");
    let mut run = Run::start();
    run.play(END);
    let pedigree = run.world.pedigree();
    let key = |sim: Option<SimId>| {
        let person = pedigree.persons.iter().find(|p| Some(p.sim) == sim)?;
        Some(person.lineage_key)
    };
    let draws = Draws::new(WorldSeed::new(0xff));
    let found: Vec<(u64, u64, u64, bool)> = pedigree
        .persons
        .iter()
        .map(|person| {
            let genome = Genome::with_alleles(person.sex, &person.alleles, &data).expect("fits");
            let parents = key(person.mother)
                .zip(key(person.father))
                .map(|(mother, father)| Parents { mother, father });
            let own = person.lineage_key;
            let l = phenotype(
                sim_core::phenotype::Environment::one(&draws),
                &data,
                &genome,
                own,
                parents,
                &code,
                SimDuration::ZERO,
            )
            .expect("a phenotype");
            let held = person
                .diseases
                .iter()
                .any(|d| d.disease.as_str() == code.as_str());
            assert_eq!(held, l > threshold, "sim {}", person.sim.get());
            (person.sim.get(), own.get(), l.to_bits(), held)
        })
        .collect();
    assert_eq!(found, LIABILITY);
}

/// A save in which a person holds the threshold disease without `L > T` (sim 3, with the
/// onset and the planned death her draws give), or lacks it with `L > T` (sim 1, without
/// her affliction and its planned death), is inconsistent; both are the save after the
/// start changed in that one person.
#[test]
fn a_save_against_the_threshold_is_rejected() {
    for bytes in [HELD_WITHOUT_L_ABOVE_T, MISSING_WITH_L_ABOVE_T] {
        assert_eq!(
            World::load(&hex(bytes), liability_data()).err(),
            Some(LoadError::Inconsistent)
        );
    }
}
